#include <stdio.h>

int main(void) {
    int S, T;
    if (scanf("%d %d", &S, &T) != 2) return 0;

    static unsigned char adj[1005][1005];

    for (int i = 0; i < T; i++) {
        int X, Y;
        scanf("%d %d", &X, &Y);
        adj[X][Y] = adj[Y][X] = 1;
    }

    int P;
    scanf("%d", &P);

    int ans = 0;

    for (int p = 0; p < P; p++) {
        int N;
        scanf("%d", &N);

        int prev = -1;
        int ok = 1;

        for (int i = 0; i < N; i++) {
            int c;
            scanf("%d", &c);

            if (i > 0 && !adj[prev][c]) {
                ok = 0;
            }

            prev = c;
        }

        if (ok) ans++;
    }

    printf("%d\n", ans);

    return 0;
}
